frame.store("_a_letter_someone_else_got", { let __signature_4921 = Signature { name: "_a_letter_someone_else_got".into(), positional: vec!["norm".into(),"verb".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4923 = Value::dict(); __attrs_4923.dict_set(Value::from("__doc__"), Value::from("Whether a possessive in front of the letter names a person other than the speaker.\n\n    \"my neighbour got a letter from the council\" and \"my wife got a letter from the school\" are\n    letters to them, not to the person writing, so there is nothing for them to answer. The\n    possessive has to sit before the letter word to count, and \"i got my letter from the\n    council\" names the letter itself, so that one keeps its summons.\n    "))?; __attrs_4923.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4924 = Value::dict(); __attrs_4923.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4920 = Frame::module(frame.globals.clone()); let mut __function_4922 = NativeFunction::qualified_with_origin("_a_letter_someone_else_got".into(), "_a_letter_someone_else_got".into(), "bot.understanding.kinds".into(), __attrs_4923, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/kinds.py", first: 5668, last: 5681, qualname: "_a_letter_someone_else_got" }, closure: __closure_4920.clone(), freevars: vec![] }, move |rt, args| __py_147::_a_letter_someone_else_got(rt, __closure_4920.clone(), &__signature_4921, args)); __function_4922 })?;
